import{_ as e,o as n,c as a,aw as o}from"./chunks/framework.DLufY-ao.js";const l="data:image/png;base64,",m=JSON.parse('{"title":"Мультивставка: insertAdjacentHTML и DocumentFragment","description":"","frontmatter":{},"headers":[],"relativePath":"wiki/dev-commit/js/js-web-api/dom/multi-insert.md","filePath":"wiki/dev-commit/js/js-web-api/dom/multi-insert.md"}'),t={name:"wiki/dev-commit/js/js-web-api/dom/multi-insert.md"};function p(c,s,r,i,d,A){return n(),a("div",null,[...s[0]||(s[0]=[o('<h1 id="мультивставка-insertadjacenthtml-и-documentfragment" tabindex="-1">Мультивставка: insertAdjacentHTML и DocumentFragment <a class="header-anchor" href="#мультивставка-insertadjacenthtml-и-documentfragment" aria-label="Permalink to &quot;Мультивставка: insertAdjacentHTML и DocumentFragment&quot;">​</a></h1><h2 id="insertadjacenthtml" tabindex="-1">insertAdjacentHTML <a class="header-anchor" href="#insertadjacenthtml" aria-label="Permalink to &quot;insertAdjacentHTML&quot;">​</a></h2><ul><li>Обычные методы вставки работают с одним узлом. Но есть и способы вставлять множество узлов одновременно</li><li><code>elem.insertAdjacentHTML(where, html)</code> - вставка строки HTML в любое место документа, в том числе и между узлами</li><li><code>elem.insertAdjacentElement(where, newElem)</code> - вставка элемента newElem</li><li><code>elem.insertAdjacentText(where, text)</code> - создаёт текстовый узел из строки text и вставляет его в указанное место относительно elem</li><li><code>where</code> - куда по отношению к elem вставлять строку <ol><li><code>beforeBegin</code> - перед elem</li><li><code>afterBegin</code> - внутрь elem, в самое начало</li><li><code>beforeEnd</code> - внутрь elem, в конец</li><li><code>afterEnd</code> - после elem</li></ol></li></ul><img src="'+l+`"><h2 id="documentfragment" tabindex="-1">DocumentFragment <a class="header-anchor" href="#documentfragment" aria-label="Permalink to &quot;DocumentFragment&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">Определение</p><ul><li><strong>DocumentFragment</strong> - лёгкий DOM-узел, который не входит в дерево документа</li></ul></div><ul><li>У DocumentFragment нет обычных свойств элементов, таких как innerHTML, tagName и т.п. Это узел, но не элемент</li><li>Когда DocumentFragment вставляется в DOM, то он исчезает, а вместо него вставляются его дети. Это свойство является особенностью DocumentFragment</li><li>DocumentFragment, в отличие от insertAdjacent*, работает с коллекцией DOM-узлов</li></ul><div class="language-js"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki one-light vp-code" tabindex="0"><code><span class="line"><span style="color:#A626A4;">const</span><span style="color:#986801;"> fragment</span><span style="color:#0184BC;"> =</span><span style="color:#383A42;"> document.</span><span style="color:#4078F2;">createDocumentFragment</span><span style="color:#383A42;">(); </span><span style="color:#A0A1A7;font-style:italic;">// Создание</span></span>
<span class="line"><span style="color:#383A42;">fragment.</span><span style="color:#4078F2;">appendChild</span><span style="color:#383A42;">(node); </span><span style="color:#A0A1A7;font-style:italic;">// Добавление узлов</span></span>
<span class="line"><span style="color:#383A42;">fragment.</span><span style="color:#4078F2;">cloneNode</span><span style="color:#383A42;">(</span><span style="color:#986801;">true</span><span style="color:#383A42;">); </span><span style="color:#A0A1A7;font-style:italic;">// Клонирование</span></span>
<span class="line"><span style="color:#383A42;">ul.</span><span style="color:#4078F2;">appendChild</span><span style="color:#383A42;">(fragment); </span><span style="color:#A0A1A7;font-style:italic;">// Вставка</span></span></code></pre></div><h3 id="пример-использования" tabindex="-1">Пример использования <a class="header-anchor" href="#пример-использования" aria-label="Permalink to &quot;Пример использования&quot;">​</a></h3><div class="language-js"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki one-light vp-code" tabindex="0"><code><span class="line"><span style="color:#A0A1A7;font-style:italic;">// Создание элемента</span></span>
<span class="line"><span style="color:#A626A4;">const</span><span style="color:#986801;"> div</span><span style="color:#0184BC;"> =</span><span style="color:#383A42;"> document.</span><span style="color:#4078F2;">createElement</span><span style="color:#383A42;">(</span><span style="color:#50A14F;">&quot;div&quot;</span><span style="color:#383A42;">);</span></span>
<span class="line"><span style="color:#383A42;">div.</span><span style="color:#E45649;">innerText</span><span style="color:#0184BC;"> =</span><span style="color:#50A14F;"> &quot;element&quot;</span><span style="color:#383A42;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#A0A1A7;font-style:italic;">// Создание fragment и добавление элемента</span></span>
<span class="line"><span style="color:#A626A4;">const</span><span style="color:#986801;"> fragment</span><span style="color:#0184BC;"> =</span><span style="color:#383A42;"> document.</span><span style="color:#4078F2;">createDocumentFragment</span><span style="color:#383A42;">();</span></span>
<span class="line"><span style="color:#383A42;">fragment.</span><span style="color:#4078F2;">appendChild</span><span style="color:#383A42;">(div);</span></span>
<span class="line"></span>
<span class="line"><span style="color:#A0A1A7;font-style:italic;">// Вывод фрагмента</span></span>
<span class="line"><span style="color:#383A42;">document.</span><span style="color:#4078F2;">querySelector</span><span style="color:#383A42;">(</span><span style="color:#50A14F;">&quot;ul&quot;</span><span style="color:#383A42;">).</span><span style="color:#4078F2;">appendChild</span><span style="color:#383A42;">(fragment);</span></span></code></pre></div><h2 id="append-prepend-before-after-replacewith" tabindex="-1">append/prepend, before/after, replaceWith <a class="header-anchor" href="#append-prepend-before-after-replacewith" aria-label="Permalink to &quot;append/prepend, before/after, replaceWith&quot;">​</a></h2><ul><li><code>node.append(...nodes)</code> - вставляет <code>nodes</code> в конец <code>node</code></li><li><code>node.prepend(...nodes)</code> - вставляет <code>nodes</code> в начало <code>node</code></li><li><code>node.after(...nodes)</code> - вставляет <code>nodes</code> после узла <code>node</code></li><li><code>node.before(...nodes)</code> - вставляет <code>nodes</code> перед узлом <code>node</code></li><li><code>node.replaceWith(...nodes)</code> - вставляет <code>nodes</code> вместо <code>node</code></li><li>Методы ничего не возвращают</li><li>Во всех методах <code>nodes</code> - DOM-узлы или строки, в любом сочетании и количестве. Причём строки вставляются именно как текстовые узлы, в отличие от <code>insertAdjacentHTML</code></li></ul><div class="language-js"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki one-light vp-code" tabindex="0"><code><span class="line"><span style="color:#A0A1A7;font-style:italic;">// Добавим элемент в конец body</span></span>
<span class="line"><span style="color:#A626A4;">const</span><span style="color:#986801;"> p</span><span style="color:#0184BC;"> =</span><span style="color:#383A42;"> document.</span><span style="color:#4078F2;">createElement</span><span style="color:#383A42;">(</span><span style="color:#50A14F;">&quot;p&quot;</span><span style="color:#383A42;">);</span></span>
<span class="line"><span style="color:#383A42;">document.</span><span style="color:#E45649;">body</span><span style="color:#383A42;">.</span><span style="color:#4078F2;">append</span><span style="color:#383A42;">(p);</span></span>
<span class="line"></span>
<span class="line"><span style="color:#A626A4;">const</span><span style="color:#986801;"> em</span><span style="color:#0184BC;"> =</span><span style="color:#383A42;"> document.</span><span style="color:#4078F2;">createElement</span><span style="color:#383A42;">(</span><span style="color:#50A14F;">&quot;em&quot;</span><span style="color:#383A42;">);</span></span>
<span class="line"><span style="color:#383A42;">em.</span><span style="color:#4078F2;">append</span><span style="color:#383A42;">(</span><span style="color:#50A14F;">&quot;Мир!&quot;</span><span style="color:#383A42;">);</span></span>
<span class="line"></span>
<span class="line"><span style="color:#A0A1A7;font-style:italic;">// Вставить в параграф текстовый и обычный узлы</span></span>
<span class="line"><span style="color:#383A42;">p.</span><span style="color:#4078F2;">append</span><span style="color:#383A42;">(</span><span style="color:#50A14F;">&quot;Привет, &quot;</span><span style="color:#383A42;">, em);</span></span>
<span class="line"></span>
<span class="line"><span style="color:#A0A1A7;font-style:italic;">// Добавить элемент после тега p</span></span>
<span class="line"><span style="color:#383A42;">p.</span><span style="color:#4078F2;">after</span><span style="color:#383A42;">(document.</span><span style="color:#4078F2;">createElement</span><span style="color:#383A42;">(</span><span style="color:#50A14F;">&quot;hr&quot;</span><span style="color:#383A42;">));</span></span></code></pre></div>`,13)])])}const u=e(t,[["render",p]]);export{m as __pageData,u as default};
